zh-to-en.css:
.card {
  text-align: center;
  font-size: 17px;
  line-height: 1.6;
}
.uc-ask {
  margin-bottom: 14px;
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  opacity: 0.55;
}
.uc-simp {
  font-family: var(--han, "Noto Sans SC", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif);
  font-size: 46px;
  font-weight: 400;
  line-height: 1.15;
}
.uc-trad {
  font-family: var(--han, "Noto Sans SC", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif);
  margin-top: 8px;
  font-size: 34px;
  font-weight: 400;
  line-height: 1.25;
  opacity: 0.5;
}
.uc-pinyin {
  margin-top: 12px;
  font-size: 21px;
  letter-spacing: 0.01em;
  opacity: 0.85;
}
.uc-zhuyin {
  font-family: var(--han, "Noto Sans SC", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif);
  margin-top: 5px;
  font-size: 17px;
  letter-spacing: 0.06em;
  opacity: 0.72;
}
.uc-mw {
  margin-top: 12px;
  font-size: 15px;
  line-height: 1.5;
}
.uc-mwlab {
  margin-right: 8px;
  font-size: 9.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  opacity: 0.5;
}
.uc-mwi + .uc-mwi {
  margin-left: 12px;
}
.uc-mwc {
  font-family: var(--han, "Noto Sans SC", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif);
  font-weight: 400;
}
.uc-mwt {
  margin-left: 4px;
  opacity: 0.5;
}
.uc-mwp {
  margin-left: 6px;
  opacity: 0.75;
}
.uc-field {
  display: block;
  width: fit-content;
  max-width: 100%;
  margin: 14px auto 0;
  padding: 11px 15px;
  border: 1px solid var(--rule, rgba(0,0,0,0.12));
  border-radius: 11px;
  text-align: left;
  background: var(--paper-2, rgba(0,0,0,0.05));
  background: color-mix(in srgb, var(--paper-2, #EFEDE6) 58%, var(--card, #FFFFFF));
}
.uc-sense {
  line-height: 1.6;
}
.uc-chars {
  display: block;
  width: fit-content;
  max-width: 100%;
  margin: 14px auto 0;
  text-align: left;
}
.uc-ch {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 3px 0;
  font-size: 14px;
}
.uc-ch + .uc-ch {
  border-top: 1px solid var(--rule, rgba(0,0,0,0.10));
}
.uc-chc {
  font-family: var(--han, "Noto Sans SC", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif);
  font-weight: 400;
  font-size: 22px;
  line-height: 1.1;
  min-width: 26px;
}
.uc-chp {
  min-width: 52px;
  opacity: 0.8;
}
.uc-chm {
  flex: 1 1 auto;
}
.uc-chr {
  opacity: 0.6;
  font-size: 12.5px;
  white-space: nowrap;
}
.uc-chr b {
  font-family: var(--han, "Noto Sans SC", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif);
  font-weight: 400;
  font-size: 15px;
}
.uc-ex {
  display: block;
  width: fit-content;
  max-width: 100%;
  margin: 14px auto 0;
  text-align: center;
}
.uc-ex > summary {
  cursor: pointer;
  list-style: none;
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  opacity: 0.6;
}
.uc-ex > summary::-webkit-details-marker {
  display: none;
}
.uc-ex > summary::after {
  content: " ▾";
}
.uc-ex[open] > summary::after {
  content: " ▴";
}
.uc-exs {
  margin-top: 9px;
}
.uc-exi + .uc-exi {
  margin-top: 9px;
}
.uc-exz {
  font-family: var(--han, "Noto Sans SC", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif);
  font-weight: 400;
  font-size: 18px;
  line-height: 1.5;
}
.uc-exz b {
  font-weight: 400;
  color: var(--zh, #C8453C);
}
.uc-exe {
  margin-top: 1px;
  font-size: 14px;
  opacity: 0.75;
}
.uc-excr {
  margin-top: 9px;
  font-size: 10.5px;
  opacity: 0.45;
}
.uc-sense + .uc-sense {
  margin-top: 2px;
}
hr {
  margin: 18px 0;
  border: 0;
  border-top: 1px solid currentColor;
  opacity: 0.18;
}
.uc-sense {
  font-size: 16px;
}
